import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"安裝","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/installation.md","filePath":"zh-TW/guide/installation.md","lastUpdated":1793173149000}`),a={name:`zh-TW/guide/installation.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h1><p>Sudoku 在 App Store 上以通用 App 形式提供，一次購買即可支援 iPhone、iPad 與 Mac。</p><h2 id="下載" tabindex="-1">下載 <a class="header-anchor" href="#下載" aria-label="Permalink to “下載”">​</a></h2><ul><li><strong>App Store</strong>：<a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">下載 Sudoku</a> — 適用於 iPhone、iPad 與 Mac 的通用 App</li></ul><h3 id="app-store-建議方式" tabindex="-1">App Store（建議方式） <a class="header-anchor" href="#app-store-建議方式" aria-label="Permalink to “App Store（建議方式）”">​</a></h3><p>App Store 版本可自動更新，並與你的所有 Apple 裝置無縫整合。</p><ul><li><strong>App Store ID</strong>：6793606018</li><li><strong>連結</strong>：<a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a></li><li><strong>平台</strong>：iPhone、iPad、Mac（通用 App）</li><li><strong>價格</strong>：目前價格請參閱 App Store 頁面</li></ul><h2 id="安裝步驟" tabindex="-1">安裝步驟 <a class="header-anchor" href="#安裝步驟" aria-label="Permalink to “安裝步驟”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>在裝置上開啟 <strong>App Store</strong></li><li>搜尋「Sudoku」，或使用上方直接連結</li><li>點一下 <strong>取得</strong> 或 <strong>購買</strong> 即可下載</li><li>App 會自動安裝</li><li>從主畫面啟動 Sudoku</li></ol><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ol><li>在 Mac 上開啟 <strong>App Store</strong></li><li>搜尋「Sudoku」，或使用上方直接連結</li><li>按一下 <strong>取得</strong> 或 <strong>購買</strong></li><li>App 會自動下載並安裝</li><li>從「應用程式」檔案夾或 Launchpad 啟動 Sudoku</li></ol><h2 id="首次啟動" tabindex="-1">首次啟動 <a class="header-anchor" href="#首次啟動" aria-label="Permalink to “首次啟動”">​</a></h2><p>第一次啟動 Sudoku 時，App 會請求存取 iCloud（用於同步）與 Game Center（用於排行榜與成就）的權限。這些都是選用的——即使不允許，遊戲仍可完全離線運作。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to “更新”">​</a></h2><p>更新由 App Store 自動處理。若要手動檢查更新，請開啟 App Store，前往 <strong>帳號 → 更新項目</strong> 區塊。</p><h2 id="解除安裝" tabindex="-1">解除安裝 <a class="header-anchor" href="#解除安裝" aria-label="Permalink to “解除安裝”">​</a></h2><h3 id="iphone-ipad-1" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad-1" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>長按 Sudoku App 圖示</li><li>點一下 <strong>移除 App</strong> → <strong>刪除 App</strong></li></ol><h3 id="mac-1" tabindex="-1">Mac <a class="header-anchor" href="#mac-1" aria-label="Permalink to “Mac”">​</a></h3><ol><li>結束 Sudoku</li><li>將 <code>Sudoku.app</code> 從 <code>Applications</code> 拖曳到垃圾桶</li><li>（選用）移除 App 資料：</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><h2 id="系統需求" tabindex="-1">系統需求 <a class="header-anchor" href="#系統需求" aria-label="Permalink to “系統需求”">​</a></h2><ul><li><strong>iPhone/iPad</strong>：iOS/iPadOS 16.0 或以上版本</li><li><strong>Mac</strong>：macOS 15.0（Sequoia）或以上版本</li><li><strong>CPU</strong>：Apple Silicon（M 系列）</li><li><strong>記憶體</strong>：至少 2GB</li><li><strong>儲存空間</strong>：約 50 MB</li><li><strong>網路</strong>：遊玩時不需要（iCloud／Game Center 為選用）</li></ul><h2 id="疑難排解" tabindex="-1">疑難排解 <a class="header-anchor" href="#疑難排解" aria-label="Permalink to “疑難排解”">​</a></h2><p>若安裝過程中遇到問題：</p><ul><li><strong>macOS 阻擋 App</strong>：開啟 <strong>系統設定 → 隱私權與安全性</strong>，對 Sudoku 按一下 <strong>仍要打開</strong></li><li><strong>App 沒有出現</strong>：重新啟動 App Store 或你的裝置後再試一次</li></ul><p>需要更多協助，請參閱<a href="./troubleshooting.html">疑難排解指南</a>，或在專案儲存庫提出 issue。</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};